                    const baseUrl = location.href.replace(location.hash, "");
                    if (typeof href === "string" && href.includes("#") && href.indexOf(baseUrl) >= 0) {
                    $(this).addClass("clinkhash");
                    }
                });
                $('.clinkhash').on('click', function(e) 
